&lt;p&gt;&lt;strong&gt;&lt;span data-contrast="auto"&gt;Desirable&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props="{}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}" data-aria-posinset="19" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="p1"&gt;Familiarity with rack-scale/multi-node systems, high-speed interconnects, and production qualification of complex assemblies.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
